<?php
require_once __DIR__.'/db.php'; require_login();
$siteId=(int)($_GET['site_id']??0);$programId=(int)($_GET['program_id']??0);$status=trim($_GET['status']??'');$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');
$where=[];$params=[];if($siteId>0){$where[]="b.site_id=?";$params[]=$siteId;}if($programId>0){$where[]="b.program_id=?";$params[]=$programId;}if($status!==''){$where[]="b.program_status=?";$params[]=$status;}if($from!==''){$where[]="hr.record_date>=?";$params[]=$from;}if($to!==''){$where[]="hr.record_date<=?";$params[]=$to;}
$whereSql=$where?'WHERE '.implode(' AND ',$where):'';
$stmt=$pdo->prepare("SELECT b.beneficiary_code,hr.record_date,b.full_name,b.birth_date,TIMESTAMPDIFF(YEAR,b.birth_date,hr.record_date) age_at_record,b.sex,b.grade_level,s.site_name,p.program_name,hr.height_cm,hr.weight_kg,hr.bmi,COALESCE(hr.nutritional_status,'Pending child reference') nutritional_status,hr.remarks FROM health_records hr JOIN beneficiaries b ON b.beneficiary_id=hr.beneficiary_id LEFT JOIN feeding_sites s ON s.site_id=b.site_id LEFT JOIN feeding_programs p ON p.program_id=b.program_id $whereSql ORDER BY hr.record_date DESC,hr.record_id DESC");$stmt->execute($params);
header('Content-Type:text/csv;charset=utf-8');header('Content-Disposition:attachment; filename="pan_cada_dia_health_report_'.date('Y-m-d_H-i-s').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Beneficiary ID','Record Date','Beneficiary','Birthdate','Age at Record','Sex','Grade/Category','Feeding Site','Program','Height (cm)','Weight (kg)','BMI','Nutritional Status','Remarks']);while($r=$stmt->fetch())fputcsv($out,array_values($r));fclose($out);exit;
